<?php
 namespace QQWorld\Setup\Module\Di\Code\Generator; use QQWorld\Framework\App\Area; use QQWorld\Framework\App\Cache\Manager; use QQWorld\Framework\App\Interception\Cache\CompiledConfig; use QQWorld\Framework\Interception\Config\Config as InterceptionConfig; use QQWorld\Setup\Module\Di\Code\Reader\Type; use QQWorld\Framework\ObjectManager\InterceptableValidator; class InterceptionConfigurationBuilder { private $areaCodesList = []; private $interceptionConfig; private $pluginList; private $typeReader; private $cacheManager; private $interceptableValidator; public function __construct( InterceptionConfig $interceptionConfig, PluginList $pluginList, Type $typeReader, Manager $cacheManager, InterceptableValidator $interceptableValidator ) { $this->interceptionConfig = $interceptionConfig; $this->pluginList = $pluginList; $this->typeReader = $typeReader; $this->cacheManager = $cacheManager; $this->interceptableValidator = $interceptableValidator; } public function addAreaCode($areaCode) { if (empty($this->areaCodesList[$areaCode])) { $this->areaCodesList[] = $areaCode; } } public function getInterceptionConfiguration($definedClasses) { $interceptedInstances = $this->getInterceptedClasses($definedClasses); $inheritedConfig = $this->getPluginsList($interceptedInstances); $mergedAreaPlugins = $this->mergeAreaPlugins($inheritedConfig); $interceptedMethods = $this->getInterceptedMethods($mergedAreaPlugins); return $interceptedMethods; } private function getInterceptedClasses($definedClasses) { $intercepted = []; foreach ($definedClasses as $definedClass) { if ($this->interceptionConfig->hasPlugins($definedClass) && $this->typeReader->isConcrete($definedClass) && $this->interceptableValidator->validate($definedClass) ) { $intercepted[] = $definedClass; } } return $intercepted; } private function getPluginsList($interceptedInstances) { $this->cacheManager->setEnabled([CompiledConfig::TYPE_IDENTIFIER], true); $this->pluginList->setInterceptedClasses($interceptedInstances); $inheritedConfig = []; foreach ($this->areaCodesList as $areaKey) { $scopePriority = [Area::AREA_GLOBAL]; $pluginListCloned = clone $this->pluginList; if ($areaKey != Area::AREA_GLOBAL) { $scopePriority[] = $areaKey; $pluginListCloned->setScopePriorityScheme($scopePriority); } $key = implode('', $scopePriority); $inheritedConfig[$key] = $this->filterNullInheritance($pluginListCloned->getPluginsConfig()); } return $inheritedConfig; } private function filterNullInheritance($pluginInheritance) { $filteredData = []; foreach ($pluginInheritance as $instance => $plugins) { if ($plugins === null || !$this->typeReader->isConcrete($instance)) { continue; } $pluginInstances = []; foreach ($plugins as $plugin) { if (in_array($plugin['instance'], $pluginInstances)) { continue; } $pluginInstances[] = $plugin['instance']; } $filteredData[$instance] = $pluginInstances; } return $filteredData; } private function mergeAreaPlugins($inheritedConfig) { $mergedConfig = []; foreach ($inheritedConfig as $configuration) { $mergedConfig = array_merge_recursive($mergedConfig, $configuration); } foreach ($mergedConfig as &$plugins) { $plugins = array_unique($plugins); } return $mergedConfig; } private function getInterceptedMethods($interceptionConfiguration) { $pluginDefinitionList = new \QQWorld\Framework\Interception\Definition\Runtime(); foreach ($interceptionConfiguration as &$plugins) { $pluginsMethods = []; foreach ($plugins as $plugin) { $pluginsMethods = array_unique( array_merge($pluginsMethods, array_keys($pluginDefinitionList->getMethodList($plugin))) ); } $plugins = $pluginsMethods; } return $interceptionConfiguration; } } 